def below_zero(operations: List[int]) -> bool:
    """
    Return True if at any point the cumulative sum of operations falls below zero.
    """
    if operations is None:
        raise TypeError("operations must be a list of integers")
    balance = 0
    for op in operations:
        try:
            balance += op
        except TypeError:
            raise TypeError(f"operation {op!r} is not an integer")
        if balance < 0:
            return True
    return False

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each path starts at (1, 1) and ends at (N, N), moving only right or down.
    A cell's value can be collected at most once, even if both paths pass through it.
    """
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Edge case: empty grid
    if N <= 0:
        return 0

    # DP arrays: dp_prev[i1][i2] = max sum when first path at (i1, j1) and second at (i2, j2)
    # where j1 = t - i1, j2 = t - i2 for current step t
    NEG_INF = -10**9
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]  # starting cell counted once

    # Iterate over all possible steps t = i + j (starting from 2 to 2N)
    for t in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 range from 1 to N, but j = t - i must be within [1, N]
        i_min = max(1, t - N)
        i_max = min(N, t - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = t - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = t - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG_INF
                # Consider previous positions for both paths (up or left)
                for pi1 in (i1 - 1, i1):
                    if pi1 < 1:
                        continue
                    for pi2 in (i2 - 1, i2):
                        if pi2 < 1:
                            continue
                        val = dp_prev[pi1][pi2]
                        if val > best:
                            best = val
                if best == NEG_INF:
                    continue
                # Add current cell values (count once if same cell)
                val = best + grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    val += grid[i2][j2]
                dp_cur[i1][i2] = val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If inputs are not of expected types.
        ValueError: If n is negative or the length of coeffs does not match n+1.
    """
    # Validate input types
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if not isinstance(coeffs, list):
        raise TypeError(f"coeffs must be a list, got {type(coeffs).__name__}")
    if any(not isinstance(c, int) for c in coeffs):
        raise TypeError("All coefficients must be integers")

    # Validate n and coeffs length
    if n < 0:
        raise ValueError("n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError(f"Length of coeffs ({len(coeffs)}) does not match n+1 ({n+1})")

    terms = []
    first_term = True

    for degree, coeff in zip(range(n, -1, -1), coeffs):
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        # Determine coefficient part
        if var_part and abs_coeff == 1:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'

    return ''.join(terms)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    # Basic type validation
    if not isinstance(A, str) or not isinstance(B, str):
        raise TypeError("A and B must be strings")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise TypeError("Each rule must be a tuple of (source, target)")
        if not isinstance(rule[0], str) or not isinstance(rule[1], str):
            raise TypeError("Rule substrings must be strings")

    # Immediate success
    if A == B:
        return 0

    # If no rules, cannot transform
    if not rules:
        return "NO ANSWER!"

    from collections import deque

    max_depth = 10
    visited = set()
    queue = deque()
    queue.append((A, 0))
    visited.add(A)

    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue  # do not expand further

        for src, tgt in rules:
            if not src:  # avoid infinite loop on empty source
                continue
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return depth + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, depth + 1))
                start = idx + 1  # allow overlapping matches

    return "NO ANSWER!"

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.

    Raises:
        TypeError: If student_scores is not a list.
        ValueError: If any element is not a tuple of length 3 or contains non-numeric values.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    # Validate each tuple
    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple):
            raise ValueError(f"Element at index {idx} is not a tuple")
        if len(item) != 3:
            raise ValueError(f"Tuple at index {idx} does not contain exactly 3 elements")
        student_number, total_score, chinese_score = item
        if not isinstance(student_number, (int, float)):
            raise ValueError(f"Student number at index {idx} is not numeric")
        if not isinstance(total_score, (int, float)):
            raise ValueError(f"Total score at index {idx} is not numeric")
        if not isinstance(chinese_score, (int, float)):
            raise ValueError(f"Chinese score at index {idx} is not numeric")

    # Perform sorting
    try:
        sorted_list = sorted(
            student_scores,
            key=lambda x: (-x[1], -x[2], x[0])
        )
    except Exception as e:
        raise RuntimeError(f"Error during sorting: {e}")

    return sorted_list
